const input = $input.first()?.json || {};
const requestedSources = input.expectedSources ?? input.body?.expectedSources;
const expectedSources = Array.isArray(requestedSources)
  ? [...new Set(requestedSources.filter((source) => source === "CO" || source === "DIEN"))]
  : ["CO", "DIEN"];

if (!expectedSources.length) {
  return [];
}

return [{
  json: {
    externalRunId: `defects-${$execution.id}`,
    expectedSources,
  },
}];

const SOURCE = {
  code: "CO",
  spreadsheetId: "1zKRH9zhEAkCwGRl4KiaNwUlkLg9_l4WXNSBeg3FK_MA",
  sheet: "CƠ_DH1",
  tab: "DH1",
  requestType: "Cơ",
};

const normalize = (value) => String(value ?? "")
  .normalize("NFD")
  .replace(/[\u0300-\u036f]/g, "")
  .replace(/đ/g, "d")
  .replace(/Đ/g, "D")
  .toLowerCase()
  .replace(/\s+/g, " ")
  .trim();

const text = (value) => String(value ?? "").trim();

function valueOf(row, aliases) {
  const entries = Object.entries(row).map(([key, value]) => [normalize(key), value]);
  for (const alias of aliases) {
    const exact = entries.find(([key]) => key === alias);
    if (exact) return text(exact[1]);
  }
  for (const alias of aliases) {
    const partial = entries.find(([key]) => key.includes(alias));
    if (partial) return text(partial[1]);
  }
  return "";
}

function sourceDate(value) {
  const match = text(value).match(/(\d{1,2})[\/-](\d{1,2})[\/-](\d{2,4})/);
  if (!match) return null;
  const year = match[3].length === 2 ? 2000 + Number(match[3]) : Number(match[3]);
  const date = new Date(Date.UTC(year, Number(match[2]) - 1, Number(match[1])));
  return Number.isNaN(date.getTime()) ? null : date.toISOString().slice(0, 10);
}

function sourceKey(record) {
  const unit = text(record.unit).toUpperCase().replace(/\s+/g, " ");
  return [
    record.sourceSpreadsheetId,
    record.sourceSheet,
    record.requestType,
    text(record.stt).replace(/\.0$/, ""),
    sourceDate(record.detectedAtRaw),
    unit === "S1" || unit === "S2" ? unit : "COMMON",
    normalize(record.positionRaw),
    normalize(record.deviceRaw),
  ].join("|");
}

const rawRecords = $input.all().map(({ json: row }) => {
  const stt = valueOf(row, ["stt (vh1)", "stt"]);
  const content = valueOf(row, ["ton tai/khuyet diem (vh1)", "ton tai/kiem khuyet (vh1)", "ton tai/kiem khuyet", "ton tai", "khiem khuyet"]);
  const detectedAtRaw = valueOf(row, ["ngay phat hien (vh1)", "ngay phat hien"]);
  if (!stt || stt.startsWith("(") || !content || !sourceDate(detectedAtRaw)) return null;

  return {
    sourceSpreadsheetId: SOURCE.spreadsheetId,
    sourceSheet: SOURCE.sheet,
    sourceTab: SOURCE.tab,
    sourceRow: Number(row.row_number || 0) + 5,
    requestType: SOURCE.requestType,
    stt,
    unit: valueOf(row, ["to may (vh1)", "to may"]),
    deviceRaw: valueOf(row, ["thiet bi (vh1)", "thiet bi"]),
    positionRaw: valueOf(row, ["cuong vi (vh1)", "cuong vi"]),
    content,
    detectedAtRaw,
    shiftLeaderRaw: valueOf(row, ["truong ca (vh1)", "truong ca"]),
    reminderRaw: valueOf(row, ["nhac lai (vh1)", "nhac lai"]),
    repeatedRepairRaw: valueOf(row, ["sua chua lap lai (vh1)", "sua chua lap lai"]),
    fireSafetyImpact: valueOf(row, ["anh huong pccc (vh1)", "anh huong pccc"]),
    environmentSafetyImpact: valueOf(row, ["moi truong, atvsld (vh1)", "moi truong, atvsld", "moi truong", "atvsld"]),
    severityRaw: valueOf(row, ["phan loai anh huong (vh1)", "phan loai anh huong", "phan loai"]),
    conditionRaw: valueOf(row, ["dk thuc hien (vh1)", "dieu kien thuc hien", "dk thuc hien"]),
    sourceStatusRaw: valueOf(row, ["ghi chu kq sua chua (vh1)", "ghi chu kq", "tinh trang khiem khuyet", "tinh trang"]),
    repairOrderNumberRaw: valueOf(row, ["so pct/l ct (sccn)", "so pct/lct (sccn)", "so pct/l ct (dtd)", "so pct/lct (dtd)", "so pct/l ct", "so pct/lct"]),
    repairSolutionRaw: valueOf(row, ["giai phap sua chua (sccn)", "giai phap sua chua (dtd)", "giai phap sua chua"]),
    repairPlanRaw: valueOf(row, ["ke hoach thuc hien (sccn)", "ke hoach thuc hien (dtd)", "ke hoach thuc hien"]),
    repairUnitRaw: valueOf(row, ["dvsc (sccn)", "dvsc (dtd)", "dvsc", "don vi sua chua"]),
    repairResultRaw: valueOf(row, ["ket qua thuc hien (sccn)", "ket qua thuc hien"]),
    repairPerformedByRaw: valueOf(row, ["nguoi thuc hien (sccn)", "nguoi thuc hien"]),
    repairStartedAtRaw: valueOf(row, ["ngay thuc hien (sccn)", "ngay thuc hien"]),
    completedAtRaw: valueOf(row, ["ngay ket thuc (sccn)", "ngay ket thuc"]),
    repairPerformedContentRaw: valueOf(row, ["noi dung da thuc hien (sccn)", "noi dung da thuc hien"]),
    repairNoteRaw: valueOf(row, ["ghi chu (sccn)"]),
    noteRaw: valueOf(row, ["ghi chu (vh1)", "ghi chu vh1", "ghi chu"]),
  };
}).filter(Boolean);

const byKey = new Map();
for (const record of rawRecords) {
  const key = sourceKey(record);
  const { sourceRow, ...stableRecord } = record;
  const stable = JSON.stringify(stableRecord);
  const previous = byKey.get(key);
  if (!previous) byKey.set(key, { record, stable });
  else if (previous.stable !== stable) throw new Error(`Sheet Cơ có khóa trùng nhưng nội dung khác: ${key}`);
}
const records = Array.from(byKey.values(), ({ record }) => record);

if (!records.length) throw new Error("Sheet Cơ không có dòng hợp lệ để đồng bộ");

const batches = [];
for (let index = 0; index < records.length; index += 500) {
  batches.push({
    json: {
      source: SOURCE.code,
      batchNumber: batches.length + 1,
      records: records.slice(index, index + 500),
    },
  });
}
return batches;

